import{_ as r,o as t,c as a,ae as n}from"./chunks/framework.Co1PSFSm.js";const m=JSON.parse('{"title":"","description":"Fresh is a full stack modern web framework for JavaScript and TypeScript\\ndevelopers, designed to build high-quality, performant,\\nand personalized web applications.\\n","frontmatter":{"description":"Fresh is a full stack modern web framework for JavaScript and TypeScript\\ndevelopers, designed to build high-quality, performant,\\nand personalized web applications.\\n"},"headers":[],"relativePath":"en/1.x/introduction/index.md","filePath":"en/1.x/introduction/index.md"}'),i={name:"en/1.x/introduction/index.md"};function o(s,e,l,d,p,c){return t(),a("div",null,[...e[0]||(e[0]=[n('<p>Fresh is a full stack modern web framework for JavaScript and TypeScript developers. It&#39;s designed for building high-quality, performant, and personalized web applications. You can use it to create your home page, a blog, an e-commerce shop, a large web application like GitHub or Twitter and more.</p><p>At its core, Fresh is a combination of a routing framework and templating engine that renders pages on demand on the server. These server rendered pages can contain areas that are made interactive on the client (also known as the <a href="https://jasonformat.com/islands-architecture" target="_blank" rel="noreferrer">Island Architecture</a>). Fresh uses <a href="https://preactjs.com" target="_blank" rel="noreferrer">Preact</a> as the JSX rendering engine.</p><p>Fresh projects can be deployed manually to any platform with <a href="https://deno.com" target="_blank" rel="noreferrer">Deno</a>, but it is intended to be deployed to an edge runtime like <a href="https://deno.com/deploy" target="_blank" rel="noreferrer">Deno Deploy</a> for the best experience.</p><p>Some stand out features:</p><ul><li>Zero config necessary</li><li>Tiny &amp; fast (no client JS is required by the framework)</li><li>Optional client side hydration of individual components</li><li>Highly resilient because of progressive enhancement and use of native browser features</li><li>TypeScript out of the box</li><li>File-system routing à la Next.js</li></ul>',5)])])}const h=r(i,[["render",o]]);export{m as __pageData,h as default};
